fn find_minimum_total_distance(x1: i8, x2: i8, x3: i8) -> i8 {
    // For three points on a line, the point that minimizes the sum of distances
    // to them is the median. If we let a ≤ b ≤ c be the sorted points, the
    // total minimum distance is (b - a) + (c - b) = c - a.
    let min_val = x1.min(x2).min(x3);
    let max_val = x1.max(x2).max(x3);
    max_val - min_val
}

